SourceCode.Declaration:
abstract class TFMListPageConfiguration extends TFMPageConfiguration
{
    boolean openEnabled;
    boolean refreshEnabled;

}

Method.Source:
[TFMPageConfigurationAttributeAttribute(true,'list/open','enabled'), TFMPageAction]
public boolean parmOpenEnabled(boolean _openEnabled = openEnabled)
{
    openEnabled = _openEnabled;
    return openEnabled;
}

[TFMPageConfigurationAttributeAttribute(true,'list/refresh','enabled', true,true,false,true), TFMPageAction]
public boolean parmRefreshEnabled(boolean _refreshEnabled = refreshEnabled)
{
    refreshEnabled = _refreshEnabled;
    return refreshEnabled;
}
